"Here in Norway many people eat pork ribs or pinnekjøtt.":"Aqui na Noruega muita gente come costela de porco ou pinnekjøtt.",
"What is pinnekjøtt?":"O que é pinnekjøtt?",
"It is salted and dried lamb. It smells strong, but tastes delicious!":"É carne de cordeiro salgada e seca. O cheiro é forte, mas o sabor é delicioso!",
"I have to taste it! We brought kutia from Ukraine.":"Preciso provar! Trouxemos kutia da Ucrânia.",
"After dinner we walk around the Christmas tree and sing Christmas carols.":"Depois do jantar, damos a volta na árvore de Natal cantando músicas natalinas.",
