"Has Santa been here?":"O Papai Noel passou por aqui?",
"Yes, and he left a present for both of you.":"Passou, e deixou um presente para vocês dois.",
"Thank you so much! This is the nicest Christmas we have had in Norway.":"Muito obrigada! Este é o Natal mais bonito que já tivemos na Noruega.",
"In Norway everyone has the right to walk freely in nature, even on private land.":"Na Noruega todo mundo tem o direito de andar livremente pela natureza, até em terras particulares.",
