"see → saw":"ver → viu",
"come → came":"vir → veio",
"Yesterday we went to the cinema.":"Ontem fomos ao cinema.",
"I lived in Kyiv before.":"Antes eu morava em Kiev.",
"Adjectives":"Adjetivos",
"An adjective agrees with its noun: en stor bil, et stort hus (+t), store biler (+e in the plural). In the definite form it always takes -e: den store bilen, det store huset. Some never change: bra, gratis, moderne.":"O adjetivo concorda com o substantivo: en stor bil, et stort hus (+t), store biler (+e no plural). Na forma definida ele sempre recebe -e: den store bilen, det store huset. Alguns nunca mudam: bra, gratis, moderne.",
"a big car":"um carro grande",
"a big house":"uma casa grande",
"big cars":"carros grandes",
"the big car":"o carro grande",
"a nice day / nice weather":"um dia bonito / tempo bom",
"We have a big house.":"Nós temos uma casa grande.",
"The red car is new.":"O carro vermelho é novo.",
"Prepositions":"Preposições",
"I — inside (i Norge, i Oslo, i huset), på — on and at many places (på skolen, på jobb, på butikken, på kino), til — to (til byen), fra — from (fra Ukraina), med — with/by (med bussen), om — about (om morgenen — in the morning).":"I — dentro (i Norge, i Oslo, i huset), på — em, sobre e em muitos lugares (på skolen, på jobb, på butikken, på kino), til — para (til byen), fra — de (fra Ukraina), med — com, de (med bussen), om — sobre, de (om morgenen — de manhã).",
"in Norway / in Bergen":"na Noruega / em Bergen",
"at school / at work":"na escola / no trabalho",
"to the shop":"para a loja",
"from Ukraine":"da Ucrânia",
"by bus":"de ônibus",
"in the morning":"de manhã",
"I come from Ukraine, but I live in Norway.":"Eu sou da Ucrânia, mas moro na Noruega.",
"We are travelling to Bergen by train.":"Vamos viajar para Bergen de trem.",
"Word order (V2)":"Ordem das palavras (V2)",
"In a Norwegian statement the verb is always in SECOND place. If the sentence starts with something other than the subject (i dag, nå, i morgen), the subject moves after the verb: “Jeg går på jobb” → “I dag går jeg på jobb”.":"Numa afirmação em norueguês, o verbo fica sempre em SEGUNDO lugar. Se a frase começa com outra coisa que não o sujeito (i dag, nå, i morgen), o sujeito vai para depois do verbo: “Jeg går på jobb” → “I dag går jeg på jobb”.",
"I am having breakfast now.":"Estou tomando café da manhã agora.",
"Now I am having breakfast.":"Agora estou tomando café da manhã.",
"Tomorrow we are leaving.":"Amanhã nós vamos viajar.",
"In winter it is cold.":"No inverno faz frio.",
"Today I am going to work.":"Hoje vou trabalhar.",
"After school Leo plays football.":"Depois da aula, o Leo joga futebol.",
"Conjunctions":"Conjunções",
"Og (and), men (but), eller (or) and så (so) join two main clauses. Fordi (because), at (that), når (when), hvis (if), selv om (although), mens (while) and før (before) start a subordinate clause — there ikke comes BEFORE the verb: “…fordi jeg ikke har tid”.":"Og (e), men (mas), eller (ou) e så (então) ligam duas orações principais. Fordi (porque), at (que), når (quando), hvis (se), selv om (embora), mens (enquanto) e før (antes que) iniciam uma oração subordinada — nela, ikke vem ANTES do verbo: “…fordi jeg ikke har tid”.",
"and":"e",
"but":"mas",
"or":"ou",
"that":"que",
"although":"embora",
"I am staying home because I am ill.":"Vou ficar em casa porque estou doente.",
"He says that he does not have time.":"Ele diz que não tem tempo.",
"Sin/si/sitt/sine and reflexive verbs":"Sin/si/sitt/sine e verbos reflexivos",
"Sin/si/sitt/sine means “one’s own” when the owner is the third-person subject: “Kari ringer broren sin” (her own brother), but “Kari ringer broren hennes” (another woman’s brother). Reflexive verbs take seg/meg/deg/oss: “Jeg gleder meg”, “Vi setter oss”.":"Sin/si/sitt/sine quer dizer “o próprio” quando o dono é o sujeito na terceira pessoa: “Kari ringer broren sin” (o próprio irmão dela), mas “Kari ringer broren hennes” (o irmão de outra mulher). Os verbos reflexivos levam seg/meg/deg/oss: “Jeg gleder meg”, “Vi setter oss”.",
"Kari calls her (own) brother.":"A Kari liga para o (próprio) irmão.",
"Kari calls her (someone else’s) brother.":"A Kari liga para o irmão dela (de outra pessoa).",
"I look forward":"estou ansioso, mal posso esperar",
"he sits down":"ele se senta",
"we hurry":"nós nos apressamos",
"Leo is looking for his ball.":"O Leo está procurando a própria bola.",
"We are looking forward to the holiday.":"Estamos ansiosos pelas férias.",
"Present perfect":"O perfeito (presente perfeito)",
"The present perfect is har + past participle. Use it when the result matters now or the action is still going on: “Jeg har bodd i Norge i to år”. With a specific past time (i går, i 2020) use the past tense. Forms: snakket, spist, bodd, gått, vært, hatt, sett, kommet, gjort, sagt.":"O perfeito é har + particípio. Use quando o resultado importa agora ou a ação ainda continua: “Jeg har bodd i Norge i to år”. Com um momento específico do passado (i går, i 2020), use o pretérito. Formas: snakket, spist, bodd, gått, vært, hatt, sett, kommet, gjort, sagt.",
