"have said":"já disse",
"I have lived in Norway for two years.":"Moro na Noruega há dois anos.",
"Have you been to Tromsø?":"Você já esteve em Tromsø?",
"The passive":"A voz passiva",
"The passive shows that something is done to the subject. Bli + participle for a specific event: “Huset ble bygd i 1990”. The s-passive for rules and regular actions: “Butikken åpnes klokka ni”, “Det snakkes norsk her”. After modals: “Søknaden må sendes i dag”.":"A voz passiva mostra que algo é feito com o sujeito. Bli + particípio para um acontecimento específico: “Huset ble bygd i 1990”. O passivo com -s para regras e ações habituais: “Butikken åpnes klokka ni”, “Det snakkes norsk her”. Depois de verbos modais: “Søknaden må sendes i dag”.",
"The house was built in 1990.":"A casa foi construída em 1990.",
"The shop opens at nine.":"A loja abre às nove.",
"The application must be sent today.":"O pedido precisa ser enviado hoje.",
"The book was written by Ibsen.":"O livro foi escrito por Ibsen.",
"Many languages are spoken in Oslo.":"Em Oslo se falam muitas línguas.",
"The position was advertised in March.":"A vaga foi anunciada em março.",
"Formal linking words":"Palavras de ligação formais",
"For essays, letters and debates: derfor (therefore), likevel (nevertheless), dessuten (moreover), ettersom (since), selv om (although), i motsetning til (unlike), på grunn av (because of) + noun, for å (in order to) + infinitive. Derfor/likevel/dessuten at the start trigger inversion: “Derfor må vi…”.":"Para redações, cartas e debates: derfor (por isso), likevel (mesmo assim), dessuten (além disso), ettersom (como, já que), selv om (embora), i motsetning til (ao contrário de), på grunn av (por causa de) + substantivo, for å (para) + infinitivo. Derfor/likevel/dessuten no começo provocam inversão: “Derfor må vi…”.",
"moreover":"além disso",
