"because of":"por causa de",
"in order to":"para, a fim de",
"unlike":"ao contrário de",
"It was raining. Nevertheless we went hiking.":"Estava chovendo. Mesmo assim fizemos a trilha.",
"The train was delayed because of the snow.":"O trem atrasou por causa da neve.",
"sounds like the “a” in “cat”":"soa como o “é” aberto de “pé”",
"like the “u” in “burn” with rounded lips":"como um “e” dito com os lábios arredondados, igual ao “eu” do francês",
"sounds like the “o” in “more”":"soa como o “ó” de “avó”",
