"Lost in the City":"Perdido na cidade",
"Excuse me, could you help me? I think I am lost.":"Com licença, pode me ajudar? Acho que estou perdido.",
"Of course. Where do you want to go?":"Claro. Aonde você quer ir?",
"I am looking for the city library.":"Estou procurando a biblioteca municipal.",
"Go straight on and turn left at the traffic lights.":"Siga em frente e vire à esquerda no semáforo.",
"Then walk past the bus stop. The library is opposite the bank.":"Depois passe pelo ponto de ônibus. A biblioteca fica em frente ao banco.",
